<template>
  <div class="wrapper">
    <div class="menu win-nav p-shadow-5" :style="{'background-color': `#${color}`}">
      <span style="flex: 1;"><!-- -->C<!-- -->o<!-- -->d<!-- -->e<!-- -->N<!-- -->a<!-- -->m<!-- -->e<!-- -->4<!-- -->2<!-- -->0<!-- --> <!-- -->=<!-- --> <!-- -->g<!-- -->a<!-- -->y<!-- --></span>
      <Button icon="pi pi-ban" class="p-button-rounded p-button-danger p-m-2" @click="closeLogs()"/>
    </div>
    <div class="menu p-shadow-5" :style="{'background-color': `#${color}`}">
      <div class="menu-header">
        <div class="p-fluid p-formgrid p-grid">
          <div class="p-field p-col">
            <Dropdown v-model="type" :options="types" optionLabel="name" placeholder="Select type"/>
          </div>
          <div class="p-field p-col">
            <span class="p-float-label">
              <InputText :class="{'p-invalid': input.length < 1}" id="username" type="text" v-model="input"/>
              <label for="username">Username</label>
            </span>
          </div>
          <div class="p-field p-col">
            <Button @click="getLogs(type, input)" label="Search" icon="pi pi-check" class="p-button-info search-btn" :loading="isLoading" :disabled="input.length < 1"/>
          </div>
        </div>
      </div>
      <!--Menu Color: <ColorPicker defaultColor="#ffffff" v-model="color" /> <Button label="Terminal" icon="pi pi-globe" class="p-button-rounded p-button-danger" @click="toggle" iconPos="right" />-->
      <div class="menu-body">
        <div id="results"></div>
      </div>
    </div>
  </div>
</template>

<script>
import Button from 'primevue/button';
import InputText from 'primevue/inputtext';
import Dropdown from 'primevue/dropdown';
import {Grid} from "gridjs";
import "gridjs/dist/theme/mermaid.css";


export default {
  name: "logs",
  components: {
    InputText, Dropdown, Button
  },
  methods: {
    closeLogs() {
      // eslint-disable-next-line no-undef
      mp.trigger("ShowLogsCEF", false);
    },
    toggle(event) {
      this.$refs.op.toggle(event);
    },
    updateLogs(columns, data) {
      this.columns = columns;
      this.data = data;
      this.grid.updateConfig({
        columns: this.columns,
        data: this.data
      }).forceRender();
    },
    getLogs(type, query) {
      this.isLoading = true;
      setTimeout(() => this.isLoading = false, 1000);
      // eslint-disable-next-line no-undef
      mp.trigger('RequestLogsFromServer', type.id, query);
    }
  },
  data() {
    return {
      terminal: false,
      color: 'ffffff',
      grid: null,
      isLoading: false,
      type: {name: 'Admin', id: 1},
      types: [
        {name: 'Admin', id: 1},
        {name: 'Sessions', id: 2},
        {name: 'Admin Record', id: 3},
      ],
      input: '',
      columns: [],
      data: []
    }
  },
  mounted() {
    this.$nextTick(function () {
      this.grid = new Grid({
        columns: this.columns,
        search: true,
        sort: true,
        pagination: {
          limit: 5
        },
        data: this.data,
      }).render(document.getElementById("results"));
    })
  },
}
</script>

<style scoped lang="scss">
.win-nav {
  display: flex;
  align-items: center;
  width: 100%;
  margin-bottom: 10px;
  font-weight: 500;
  font-size: 20px;
  padding: 5px 10px 5px 20px !important;
}

::v-deep(.dark-demo-terminal) {
  border-radius: 10px;
  background-color: #212121;
  color: #ffffff;

  .p-terminal-command {
    color: #80CBC4;
  }

  .p-terminal-prompt {
    color: #FFD54F;
  }

  .p-terminal-response {
    color: #9FA8DA;
  }
}
.wrapper {
  height: 100vh;
  width: 100vw;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #1f1f1f1f;
  flex-direction: column;
}

.menu {
  padding: 10px;
  width: 700px;
  border-radius: 10px;
}

.search-btn {
  height: 100%;
}
</style>